CREATE TABLE IF NOT EXISTS `#__decarofinance_budgets` (`id` INT UNSIGNED NOT NULL AUTO_INCREMENT,`title` VARCHAR(255) NOT NULL,`period_start` DATE NULL,`period_end` DATE NULL,`owner_component` VARCHAR(100) NULL,`owner_entity` VARCHAR(100) NULL,`owner_id` VARCHAR(191) NULL,`currency` CHAR(3) NOT NULL DEFAULT 'EUR',`state` TINYINT NOT NULL DEFAULT 1,`created` DATETIME NOT NULL,`created_by` INT UNSIGNED NOT NULL DEFAULT 0,PRIMARY KEY (`id`),KEY `idx_state` (`state`),KEY `idx_owner` (`owner_component`,`owner_entity`,`owner_id`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 DEFAULT COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS `#__decarofinance_budget_lines` (`id` INT UNSIGNED NOT NULL AUTO_INCREMENT,`budget_id` INT UNSIGNED NOT NULL,`kind` VARCHAR(16) NOT NULL,`code` VARCHAR(64) NULL,`category` VARCHAR(100) NULL,`title` VARCHAR(255) NOT NULL,`planned_amount` DECIMAL(15,2) NOT NULL DEFAULT 0.00,PRIMARY KEY (`id`),KEY `idx_budget` (`budget_id`),KEY `idx_category` (`category`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 DEFAULT COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS `#__decarofinance_obligations` (`id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,`external_key` VARCHAR(191) NULL,`source_component` VARCHAR(100) NULL,`source_entity` VARCHAR(100) NULL,`source_id` VARCHAR(191) NULL,`debtor_component` VARCHAR(100) NULL,`debtor_entity` VARCHAR(100) NULL,`debtor_id` VARCHAR(191) NULL,`kind` VARCHAR(64) NOT NULL,`description` VARCHAR(500) NULL,`amount` DECIMAL(15,2) NOT NULL DEFAULT 0.00,`currency` CHAR(3) NOT NULL DEFAULT 'EUR',`due_date` DATE NULL,`status` VARCHAR(32) NOT NULL DEFAULT 'open',`created` DATETIME NOT NULL,`created_by` INT UNSIGNED NOT NULL DEFAULT 0,PRIMARY KEY (`id`),UNIQUE KEY `uq_external_key` (`external_key`),KEY `idx_source` (`source_component`,`source_entity`,`source_id`),KEY `idx_debtor` (`debtor_component`,`debtor_entity`,`debtor_id`),KEY `idx_status_due` (`status`,`due_date`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 DEFAULT COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS `#__decarofinance_payments` (`id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,`external_key` VARCHAR(191) NULL,`payer_component` VARCHAR(100) NULL,`payer_entity` VARCHAR(100) NULL,`payer_id` VARCHAR(191) NULL,`amount` DECIMAL(15,2) NOT NULL DEFAULT 0.00,`currency` CHAR(3) NOT NULL DEFAULT 'EUR',`paid_at` DATETIME NULL,`method` VARCHAR(64) NULL,`reference` VARCHAR(191) NULL,`created` DATETIME NOT NULL,`created_by` INT UNSIGNED NOT NULL DEFAULT 0,PRIMARY KEY (`id`),UNIQUE KEY `uq_external_key` (`external_key`),KEY `idx_payer` (`payer_component`,`payer_entity`,`payer_id`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 DEFAULT COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS `#__decarofinance_payment_allocations` (`id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,`payment_id` BIGINT UNSIGNED NOT NULL,`obligation_id` BIGINT UNSIGNED NOT NULL,`amount` DECIMAL(15,2) NOT NULL DEFAULT 0.00,PRIMARY KEY (`id`),UNIQUE KEY `uq_payment_obligation` (`payment_id`,`obligation_id`),KEY `idx_obligation` (`obligation_id`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 DEFAULT COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS `#__decarofinance_deposit_accounts` (`id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,`owner_component` VARCHAR(100) NOT NULL,`owner_entity` VARCHAR(100) NOT NULL,`owner_id` VARCHAR(191) NOT NULL,`currency` CHAR(3) NOT NULL DEFAULT 'EUR',`state` TINYINT NOT NULL DEFAULT 1,PRIMARY KEY (`id`),UNIQUE KEY `uq_owner_currency` (`owner_component`,`owner_entity`,`owner_id`,`currency`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 DEFAULT COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS `#__decarofinance_deposit_movements` (`id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,`account_id` BIGINT UNSIGNED NOT NULL,`external_key` VARCHAR(191) NULL,`movement_type` VARCHAR(32) NOT NULL,`amount` DECIMAL(15,2) NOT NULL,`description` VARCHAR(500) NULL,`source_component` VARCHAR(100) NULL,`source_entity` VARCHAR(100) NULL,`source_id` VARCHAR(191) NULL,`created` DATETIME NOT NULL,`created_by` INT UNSIGNED NOT NULL DEFAULT 0,PRIMARY KEY (`id`),UNIQUE KEY `uq_external_key` (`external_key`),KEY `idx_account_created` (`account_id`,`created`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 DEFAULT COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS `#__decarofinance_transactions` (`id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,`external_key` VARCHAR(191) NULL,`account_id` BIGINT UNSIGNED NULL,`budget_line_id` INT UNSIGNED NULL,`direction` VARCHAR(16) NOT NULL,`category` VARCHAR(100) NULL,`amount` DECIMAL(15,2) NOT NULL DEFAULT 0.00,`currency` CHAR(3) NOT NULL DEFAULT 'EUR',`occurred_at` DATETIME NOT NULL,`source_component` VARCHAR(100) NULL,`source_entity` VARCHAR(100) NULL,`source_id` VARCHAR(191) NULL,`counterparty_component` VARCHAR(100) NULL,`counterparty_entity` VARCHAR(100) NULL,`counterparty_id` VARCHAR(191) NULL,`evidence_component` VARCHAR(100) NULL,`evidence_entity` VARCHAR(100) NULL,`evidence_id` VARCHAR(191) NULL,`description` VARCHAR(500) NULL,`created` DATETIME NOT NULL,`created_by` INT UNSIGNED NOT NULL DEFAULT 0,PRIMARY KEY (`id`),UNIQUE KEY `uq_external_key` (`external_key`),KEY `idx_occurred` (`occurred_at`),KEY `idx_account` (`account_id`),KEY `idx_budget_line` (`budget_line_id`),KEY `idx_category` (`category`),KEY `idx_source` (`source_component`,`source_entity`,`source_id`),KEY `idx_counterparty` (`counterparty_component`,`counterparty_entity`,`counterparty_id`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 DEFAULT COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS `#__decarofinance_accounts` (`id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,`external_key` VARCHAR(191) NULL,`code` VARCHAR(64) NULL,`owner_component` VARCHAR(100) NULL,`owner_entity` VARCHAR(100) NULL,`owner_id` VARCHAR(191) NULL,`name` VARCHAR(255) NOT NULL,`account_type` VARCHAR(32) NOT NULL DEFAULT 'bank',`identifier` VARCHAR(191) NULL,`currency` CHAR(3) NOT NULL DEFAULT 'EUR',`opening_balance` DECIMAL(15,2) NOT NULL DEFAULT 0.00,`state` TINYINT NOT NULL DEFAULT 1,`created` DATETIME NOT NULL,`created_by` INT UNSIGNED NOT NULL DEFAULT 0,PRIMARY KEY (`id`),UNIQUE KEY `uq_external_key` (`external_key`),KEY `idx_code` (`code`),KEY `idx_owner` (`owner_component`,`owner_entity`,`owner_id`),KEY `idx_state` (`state`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 DEFAULT COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS `#__decarofinance_orders` (`id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,`external_key` VARCHAR(191) NULL,`direction` VARCHAR(16) NOT NULL,`account_id` BIGINT UNSIGNED NULL,`budget_line_id` INT UNSIGNED NULL,`owner_component` VARCHAR(100) NULL,`owner_entity` VARCHAR(100) NULL,`owner_id` VARCHAR(191) NULL,`counterparty_component` VARCHAR(100) NULL,`counterparty_entity` VARCHAR(100) NULL,`counterparty_id` VARCHAR(191) NULL,`category` VARCHAR(100) NULL,`description` VARCHAR(500) NULL,`amount` DECIMAL(15,2) NOT NULL DEFAULT 0.00,`currency` CHAR(3) NOT NULL DEFAULT 'EUR',`due_date` DATE NULL,`required_approvals` TINYINT UNSIGNED NOT NULL DEFAULT 2,`status` VARCHAR(32) NOT NULL DEFAULT 'draft',`source_component` VARCHAR(100) NULL,`source_entity` VARCHAR(100) NULL,`source_id` VARCHAR(191) NULL,`evidence_component` VARCHAR(100) NULL,`evidence_entity` VARCHAR(100) NULL,`evidence_id` VARCHAR(191) NULL,`approved_at` DATETIME NULL,`executed_at` DATETIME NULL,`transaction_id` BIGINT UNSIGNED NULL,`created` DATETIME NOT NULL,`created_by` INT UNSIGNED NOT NULL DEFAULT 0,PRIMARY KEY (`id`),UNIQUE KEY `uq_external_key` (`external_key`),KEY `idx_status_due` (`status`,`due_date`),KEY `idx_owner` (`owner_component`,`owner_entity`,`owner_id`),KEY `idx_account` (`account_id`),KEY `idx_budget_line` (`budget_line_id`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 DEFAULT COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS `#__decarofinance_order_approvals` (`id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,`order_id` BIGINT UNSIGNED NOT NULL,`step` TINYINT UNSIGNED NOT NULL,`role` VARCHAR(64) NULL,`user_id` INT UNSIGNED NOT NULL,`decision` VARCHAR(16) NOT NULL DEFAULT 'approved',`note` VARCHAR(500) NULL,`decided_at` DATETIME NOT NULL,PRIMARY KEY (`id`),UNIQUE KEY `uq_order_step` (`order_id`,`step`),KEY `idx_user` (`user_id`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 DEFAULT COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS `#__decarofinance_transfers` (`id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,`external_key` VARCHAR(191) NULL,`from_account_id` BIGINT UNSIGNED NOT NULL,`to_account_id` BIGINT UNSIGNED NOT NULL,`amount` DECIMAL(15,2) NOT NULL DEFAULT 0.00,`currency` CHAR(3) NOT NULL DEFAULT 'EUR',`occurred_at` DATETIME NOT NULL,`description` VARCHAR(500) NULL,`source_component` VARCHAR(100) NULL,`source_entity` VARCHAR(100) NULL,`source_id` VARCHAR(191) NULL,`out_transaction_id` BIGINT UNSIGNED NULL,`in_transaction_id` BIGINT UNSIGNED NULL,`created` DATETIME NOT NULL,`created_by` INT UNSIGNED NOT NULL DEFAULT 0,PRIMARY KEY (`id`),UNIQUE KEY `uq_external_key` (`external_key`),KEY `idx_from_account` (`from_account_id`),KEY `idx_to_account` (`to_account_id`),KEY `idx_occurred` (`occurred_at`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 DEFAULT COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS `#__decarofinance_cash_checks` (`id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,`external_key` VARCHAR(191) NULL,`account_id` BIGINT UNSIGNED NOT NULL,`checked_at` DATETIME NOT NULL,`expected_balance` DECIMAL(15,2) NOT NULL DEFAULT 0.00,`actual_balance` DECIMAL(15,2) NOT NULL DEFAULT 0.00,`difference` DECIMAL(15,2) NOT NULL DEFAULT 0.00,`note` VARCHAR(1000) NULL,`evidence_component` VARCHAR(100) NULL,`evidence_entity` VARCHAR(100) NULL,`evidence_id` VARCHAR(191) NULL,`created` DATETIME NOT NULL,`created_by` INT UNSIGNED NOT NULL DEFAULT 0,PRIMARY KEY (`id`),UNIQUE KEY `uq_external_key` (`external_key`),KEY `idx_account_checked` (`account_id`,`checked_at`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 DEFAULT COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS `#__decarofinance_statements` (`id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,`external_key` VARCHAR(191) NULL,`owner_component` VARCHAR(100) NULL,`owner_entity` VARCHAR(100) NULL,`owner_id` VARCHAR(191) NULL,`statement_type` VARCHAR(32) NOT NULL,`title` VARCHAR(255) NOT NULL,`period_start` DATE NULL,`period_end` DATE NULL,`currency` CHAR(3) NOT NULL DEFAULT 'EUR',`status` VARCHAR(32) NOT NULL DEFAULT 'draft',`source_component` VARCHAR(100) NULL,`source_entity` VARCHAR(100) NULL,`source_id` VARCHAR(191) NULL,`document_component` VARCHAR(100) NULL,`document_entity` VARCHAR(100) NULL,`document_id` VARCHAR(191) NULL,`finalised_at` DATETIME NULL,`finalised_by` INT UNSIGNED NULL,`approved_at` DATETIME NULL,`approved_by` INT UNSIGNED NULL,`created` DATETIME NOT NULL,`created_by` INT UNSIGNED NOT NULL DEFAULT 0,PRIMARY KEY (`id`),UNIQUE KEY `uq_external_key` (`external_key`),KEY `idx_owner_period` (`owner_component`,`owner_entity`,`owner_id`,`period_end`),KEY `idx_type_status` (`statement_type`,`status`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 DEFAULT COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS `#__decarofinance_statement_lines` (`id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,`statement_id` BIGINT UNSIGNED NOT NULL,`section_code` VARCHAR(64) NULL,`line_code` VARCHAR(64) NULL,`label` VARCHAR(255) NOT NULL,`line_type` VARCHAR(32) NOT NULL DEFAULT 'amount',`amount` DECIMAL(15,2) NULL,`text_value` TEXT NULL,`sort_order` INT NOT NULL DEFAULT 0,`source_component` VARCHAR(100) NULL,`source_entity` VARCHAR(100) NULL,`source_id` VARCHAR(191) NULL,`created` DATETIME NOT NULL,`created_by` INT UNSIGNED NOT NULL DEFAULT 0,PRIMARY KEY (`id`),KEY `idx_statement_sort` (`statement_id`,`sort_order`,`id`),KEY `idx_line_code` (`line_code`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 DEFAULT COLLATE=utf8mb4_unicode_ci;
